import assert from 'node:assert/strict';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {spawnSync} from 'node:child_process';
import {pathToFileURL} from 'node:url';
import {resolve} from 'node:path';
import {createHash} from 'node:crypto';
import ts from 'typescript';
const base='.local/step07-r7-zip-fix', old=spawnSync('git',['show','f5740c1fd0e9e22a4f4676de51b7fd2555bc05a5:apps/api/tests/studio/integration.test.ts'],{encoding:'utf8'});assert.equal(old.status,0);
const crc=old.stdout.slice(old.stdout.indexOf('function crc(bytes:'),old.stdout.indexOf('function chunk('));const helper=old.stdout.slice(old.stdout.indexOf('function r4DownloadedFiles('),old.stdout.indexOf("it('R4 real COMMIT"));
const adapter=`import assert from 'node:assert/strict';function expect(v){return {toBe:x=>assert.equal(v,x),toEqual:x=>assert.deepEqual(v,x),toBeUndefined:()=>assert.equal(v,undefined)}};`;
await writeFile(base+'/old-reader.mjs',adapter+ts.transpileModule(crc+helper+'\nexport {r4DownloadedFiles};',{compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022}}).outputText);
const newer=await readFile('apps/api/tests/studio/stored-zip.ts','utf8');await writeFile(base+'/new-reader.mjs',ts.transpileModule(newer,{compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022}}).outputText);
const oldReader=(await import(pathToFileURL(resolve(base+'/old-reader.mjs')).href)).r4DownloadedFiles,newReader=(await import(pathToFileURL(resolve(base+'/new-reader.mjs')).href)).readStoredStandardZip;
const names=spawnSync('python3',['-c',`from pathlib import Path;print('\\n'.join(str(p) for p in sorted(Path('${base}/r7-original/zip-full-case').glob('*.zip'))))`],{encoding:'utf8'}).stdout.trim().split('\n');let rows=[];
for(const path of names){const bytes=await readFile(path);let oldAccept=true,newAccept=true,newError=null;try{oldReader(bytes)}catch{oldAccept=false}try{newReader(bytes)}catch(e){newAccept=false;newError=String(e)}const bad=path.endsWith('-central-crc.zip');assert.equal(oldAccept,true);assert.equal(newAccept,!bad);rows.push({path,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex'),oldHelperAccepted:oldAccept,newHelperAccepted:newAccept,scope:bad?'NEGATIVE_CORRECTLY_REJECTED_NOT_ARTIFACT_PASS':'NORMAL_ARCHIVE_ACCEPTED',newError});}
const first=await readFile(names.find(n=>n.endsWith('-original.zip')));await mkdir(base+'/actual-mutants',{recursive:true});const end=first.length-22,c=first.readUInt32LE(end+16);for(const [name,mutate] of [['central-name',b=>b.write('../bad',c+46)],['eocd-count',b=>{b.writeUInt16LE(9,end+8);b.writeUInt16LE(9,end+10)}],['local-crc',b=>{b[14]^=1}],['payload',b=>{b[30+b.readUInt16LE(26)]^=1}]]){const b=Buffer.from(first);mutate(b);await writeFile(base+'/actual-mutants/'+name+'.zip',b);assert.throws(()=>newReader(b));let accepts=true;try{oldReader(b)}catch{accepts=false}if(name==='central-name'||name==='eocd-count')assert.equal(accepts,true);rows.push({path:base+'/actual-mutants/'+name+'.zip',bytes:b.length,sha256:createHash('sha256').update(b).digest('hex'),oldHelperAccepted:accepts,newHelperAccepted:false});}
await writeFile(base+'/reader-comparison.json',JSON.stringify({originalHelperSHA256:createHash('sha256').update(helper).digest('hex'),oldExpectAdapter:'Only equivalent assert comparison methods; original crc/helper byte source retained',currentHelperSHA256:createHash('sha256').update(newer).digest('hex'),rows},null,2)+'\n');console.log('4 real normals accepted;4 original R7 centralCRC and4 actual archive mutants rejected; old central/name/count false acceptance confirmed');
